#pragma once

#include <sstream>
#include <string>
#include <vector>

namespace llm_npc {

// A Persona is the static identity of an NPC. It is rendered into a single
// system-prompt string that is prepended to every chat request.
struct Persona {
    std::string name;                 // "Companion", "Jim", "Jane #47"
    std::string role;                 // "traveling companion", "pharmacist"
    std::vector<std::string> traits;  // "curious", "soft-spoken", ...
    std::string speakingStyle;        // "short sentences, 1-3 per reply"
    std::string knowledgeBoundary;    // what they do / do not know
    std::string extraDirectives;      // free-form constraints

    std::string renderSystemPrompt() const {
        std::ostringstream o;
        o << "You are " << name;
        if (!role.empty()) o << ", a " << role;
        o << ".\n";
        if (!traits.empty()) {
            o << "Personality: ";
            for (size_t i = 0; i < traits.size(); ++i) {
                if (i) o << ", ";
                o << traits[i];
            }
            o << ".\n";
        }
        if (!speakingStyle.empty()) o << "Speaking style: " << speakingStyle << "\n";
        if (!knowledgeBoundary.empty()) o << "Knowledge: " << knowledgeBoundary << "\n";
        if (!extraDirectives.empty()) o << extraDirectives << "\n";
        o << "Stay in character. Never break the fourth wall. "
             "Never mention being an AI or a language model.";
        return o.str();
    }
};

}  // namespace llm_npc
#pragma once

#include <string>
#include <vector>

#include "Math.hpp"

namespace llm_npc {

// An axis-aligned solid block of the city: a building, kiosk, fountain,
// parked car — anything the player cannot walk through.
struct Building {
    std::string id;    // stable identifier, e.g. "bakery"
    std::string name;  // sign / label text; empty for filler and obstacles
    float minX = 0.f;
    float minZ = 0.f;
    float maxX = 0.f;
    float maxZ = 0.f;
    float height = 0.f;
    int facadeKind = 0;  // texture/tint selector for the renderer
};

// The walkable city: a square ground plane bounded at +-halfSize() with
// solid axis-aligned buildings. Collision treats the player as a circle on
// the ground (XZ) plane.
class City {
   public:
    // The hand-laid downtown map: 3x3 blocks, named shops on street fronts,
    // an open plaza in the middle, and a park in the north-east corner.
    static City makeDowntown();

    // Half the side length of the square world; walkable X/Z are within
    // [-halfSize, halfSize].
    float halfSize() const { return halfSize_; }

    const std::vector<Building>& buildings() const { return buildings_; }

    // Find a building by id; nullptr when absent.
    const Building* findBuilding(const std::string& id) const;

