# Plain-make test runner for the SFML-free core library.
#
# The dev container has g++/make but no cmake or SFML, so this Makefile is the
# primary way to build and run unit tests there. It compiles every
# src/core/*.cpp plus every tests/test_*.cpp into one doctest binary.
#
#   make -C tests test     # build + run all tests
#   make -C tests clean    # remove build artifacts

CXX      ?= g++
CXXFLAGS ?= -std=c++17 -g -O0 -pthread -Wall -Wextra
INCLUDES := -I../src/core -I../external -I.

BUILD  := build
TARGET := $(BUILD)/run_tests

CORE_SRCS := $(wildcard ../src/core/*.cpp)
TEST_SRCS := $(wildcard test_*.cpp)

CORE_OBJS := $(patsubst ../src/core/%.cpp,$(BUILD)/core_%.o,$(CORE_SRCS))
TEST_OBJS := $(patsubst %.cpp,$(BUILD)/%.o,$(TEST_SRCS))

.PHONY: test build clean

test: $(TARGET)
	./$(TARGET)

build: $(TARGET)

$(TARGET): $(CORE_OBJS) $(TEST_OBJS)
	$(CXX) $(CXXFLAGS) $^ -o $@

$(BUILD)/core_%.o: ../src/core/%.cpp | $(BUILD)
	$(CXX) $(CXXFLAGS) $(INCLUDES) -c $< -o $@

$(BUILD)/%.o: %.cpp | $(BUILD)
	$(CXX) $(CXXFLAGS) $(INCLUDES) -c $< -o $@

$(BUILD):
	mkdir -p $(BUILD)

clean:
	rm -rf $(BUILD)
---
#include "Npc.hpp"

#include <utility>

namespace llm_npc {

Npc::Npc(Persona persona, LlmClient& client, int maxHistoryTurns)
    : persona_(std::move(persona)), client_(client), maxHistoryTurns_(maxHistoryTurns) {}

std::uint64_t Npc::ask(const std::string& playerLine) {
    // Send a snapshot of the current history; the player line is appended to
    // history only once a successful reply arrives. That way a failed request
    // can be retried without polluting context with unanswered user turns.
    pendingUserLine_ = playerLine;
    pendingId_ = client_.submit(persona_.renderSystemPrompt(), history_, playerLine);
    return pendingId_;
}

std::optional<std::string> Npc::onReplyArrived(const ChatReply& reply) {
    if (reply.id != pendingId_) return std::nullopt;
    pendingId_ = 0;

    if (!reply.ok) {
        // Don't append anything on failure — let the UI report the error and
        // let the player retry. Clear the pending user line too.
        pendingUserLine_.clear();
        return std::nullopt;
    }

    history_.push_back({"user", std::move(pendingUserLine_)});

