    CHECK(npc.combatState() == NpcState::Hostile);
    npc.takeDamage(20);
    CHECK(npc.combatState() == NpcState::Hostile);
    CHECK(npc.hp() == 60);
}

TEST_CASE("isArmed matches persona armed flag") {
    CHECK_FALSE(makeCivilian().isArmed());
    CHECK(makeCop().isArmed());
}

